yakit.AutoInitYakit()  

// 微信AppId找归属：  
// 网络游客工具箱小程序  
// https://open.kainy.cn/  

// 在线测试接口地址：  
// https://mp.weixin.qq.com/debug  
yakit.Info(`在线测试接口地址：  
https://mp.weixin.qq.com/debug  `)
// 设置CLI应用信息  
cli.SetCliName("微信小程序工具")  
cli.SetDoc("微信小程序开发者工具，支持Token获取、域名配置查询、用户管理等功能")  

// 基础参数配置  
AppId = cli.String("AppId", cli.setHelp("微信小程序AppId，仅获取Token时需要"))  

AppSecret = cli.String(  
    "AppSecret",   
    cli.setHelp("微信小程序AppSecret，仅获取Token时需要"),
)  

access_token = cli.String("access_token", cli.setHelp("访问令牌，除获取Token外的所有操作都需要"), cli.setVerboseName("访问令牌"))

// 操作选择  
action = cli.StringSlice(  
    "action",   
    cli.setVerboseName("操作类型"),   
    cli.setHelp("选择要执行的操作"),   
    cli.setMultipleSelect(false),   
    cli.setDefault("token"),   
    cli.setSelectOption("获取Token", "token"),   
    cli.setSelectOption("查询域名配置", "getwxadevinfo"),   
    cli.setSelectOption("获取长期订阅用户", "get_wxa_followers"),   
    cli.setSelectOption("获取用户列表(前50条)", "user"),   
    cli.setSelectOption("获取用户反馈列表", "feedback"),   
    cli.setRequired(true),   
)  

// 参数验证  
cli.check()  

// 业务逻辑验证  
selectedAction = ""  
if len(action) > 0 {  
    selectedAction = action[0]  
}  

// 检查获取Token操作的必需参数    
if selectedAction == "token" {  
    if AppId == "" || AppSecret == "" {  
        yakit.Warn("获取Token操作需要提供AppId和AppSecret参数")  
        return  
    }  
} else if access_token == "" {  
    yakit.Warn("此操作需要提供access_token参数")  
    return  
}  

// API配置 - 分离路径和参数  
resConfig = {    
    "token": {    
        "path": "/cgi-bin/token",  
        "method": "GET",  
        "params": {  
            "grant_type": "client_credential",  
            "appid": AppId,  
            "secret": AppSecret  
        }  
    },    
    "getwxadevinfo": {    
        "path": "/wxa/getwxadevinfo",  
        "method": "POST",  
        "params": {  
            "access_token": access_token  
        }  
    },    
    "get_wxa_followers": {    
        "path": "/wxa/business/get_wxa_followers",  
        "method": "POST",  
        "params": {  
            "access_token": access_token  
        }  
    },    
    "user": {    
        "path": "/cgi-bin/user/get",  
        "method": "POST",  
        "params": {  
            "count": "10000",  
            "access_token": access_token  
        }  
    },    
    "feedback": {    
        "path": "/wxaapi/feedback/list",  
        "method": "GET",  
        "params": {  
            "access_token": access_token  
        }  
    }  
}  

// 启用文本显示  
yakit.EnableText("请求详情")  
yakit.EnableText("响应详情")  

// 获取API配置  
apiConfig = resConfig[selectedAction]  
apiPath = apiConfig["path"]  
apiMethod = apiConfig["method"]  
apiParams = apiConfig["params"]  

// 发送HTTP请求  
rsp, req, err = poc.HTTP(  
    poc.BasicRequest(),  
    poc.https(true),  
    poc.replaceHost("api.weixin.qq.com"),  
    poc.replacePath(apiPath),  
    poc.replaceMethod(apiMethod),
    poc.replaceAllQueryParams(apiParams)  
)
body=json.dumps(json.loads(poc.GetHTTPPacketBody(rsp)))


if err != nil {  
    yakit.Error(f"请求失败: ${err}")  
    yakit.TextTabData("响应详情", f"错误: ${err}")  
    return  
}  

// 显示请求详情  
yakit.TextTabData("请求详情", string(req))
//响应结果
r=""
// 如果是获取Token操作，尝试解析token  
if selectedAction == "token" {  
    // 微信API错误码映射表  
    errorCodeMap = {  
        "-1": "系统繁忙，此时请开发者稍候再试",  
        "40001": "获取 access_token 时 AppSecret 错误，或者 access_token 无效。请开发者认真比对 AppSecret 的正确性，或查看是否正在为恰当的公众号调用接口",  
        "40013": "不合法的 AppID ，请开发者检查 AppID 的正确性，避免异常字符，注意大小写",  
        "40002": "不合法的凭证类型",  
        "40125": "请检查 secret 的正确性，避免异常字符，注意大小写",  
        "40164": "请在接口IP白名单中进行设置",  
        "41004": "缺少 secret 参数",  
        "50004": "禁止使用 token 接口",  
        "50007": "账号已冻结",  
        "61024": "第三方平台 API 需要使用第三方平台专用 token",  
        "40243": "AppSecret已被冻结，请登录小程序平台解冻后再次调用。"  
    }  
    jbody=json.loads(poc.GetHTTPPacketBody(rsp))
    //yakit.Info(string(jbody["errcode"]))
    //追加错误详情
    if errorCodeMap[string(jbody["errcode"])]{
        r=string(body)+f"\n\n解决方案:\n${errorCodeMap[string(jbody["errcode"])]}"
    }else{
        r=string(body)
    }
}else{
    r=string(body)
}

// 显示响应详情  
yakit.TextTabData("响应详情", r)
